/// Converts a variable-length [`BinaryViewArray`] into a [`FixedSizeBinaryArray`] of `size`.
///
/// Every non-null value must have a byte length equal to `size`, otherwise a `ComputeError` is
/// raised pointing at the first mismatching value. Nulls are preserved (their backing bytes are
/// zero-filled).
fn binview_to_fixed_size_binary(
    array: &BinaryViewArray,
    size: usize,
    dtype: ArrowDataType,
) -> PolarsResult<Box<dyn Array>> {
    let mut values: Vec<u8> = Vec::with_capacity(array.len() * size);

    for (i, opt_value) in array.iter().enumerate() {
        match opt_value {
            Some(value) => {
                polars_ensure!(
                    value.len() == size,
                    ComputeError:
                    "bytes at index {} had mismatching length {}", i, value.len()
                );
                values.extend_from_slice(value);
            },
            // Zero-fill nulls to keep the buffer a multiple of `size`; validity carries the null.
            None => values.resize(values.len() + size, 0),
        }
    }

    let arr = FixedSizeBinaryArray::try_new(dtype, values.into(), array.validity().cloned())?;

    Ok(Box::new(arr))
